style:
/* 雅黛 —— 灰蓝通栏标题带，姓名与求职意向同行，日期左栏成列 */

.tw-yadai.layout-formal.resume-paper .paper-header {
  margin-bottom: 6mm;
  padding-bottom: 4.2mm;
  border-bottom: none;
}

.tw-yadai.layout-formal.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 8mm;
}

.tw-yadai.layout-formal.resume-paper .paper-header__main {
  flex: 1 1 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 5mm;
  min-width: 0;
}

.tw-yadai.layout-formal.resume-paper .paper-photo {
  order: 3;
  width: 24mm;
  height: 33mm;
  border: 0.4mm solid #dfe4ea;
  border-radius: 0;
  box-shadow: none;
}

.tw-yadai.layout-formal.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef1f4;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-yadai.layout-formal.resume-paper .paper-name-row {
  flex: 0 0 auto;
}

.tw-yadai.layout-formal.resume-paper .paper-name {
  color: #1f2b33;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.3);
  letter-spacing: 0.12em;
}

.tw-yadai.layout-formal.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #6c7c86;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-yadai.layout-formal.resume-paper .paper-role {
  flex: 0 0 auto;
  margin-top: 0;
  margin-left: auto;
  color: #2b3a44;
  font-size: calc(var(--paper-base-size) * 0.98);
  font-weight: 500;
  letter-spacing: 0.02em;
}

.tw-yadai.layout-formal.resume-paper .paper-role__label {
  display: none;
}

.tw-yadai.layout-formal.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #8595a0;
  font-weight: 400;
}

.tw-yadai.layout-formal.resume-paper .paper-contacts {
  display: grid;
  flex: 1 0 100%;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 10mm;
  margin-top: 5mm;
  padding: 3mm 0;
  border-top: 0.25mm solid #e1e6eb;
  border-bottom: 0.25mm solid #e1e6eb;
  color: #33434d;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-yadai.layout-formal.resume-paper .paper-contact {
  display: flex;
  gap: 2.2mm;
}

.tw-yadai.layout-formal.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-yadai.layout-formal.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: #8394a0;
}

/* 标题：整条灰蓝色带，白字 + 左侧图标 */
.tw-yadai.layout-formal.resume-paper .paper-style-block .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin-bottom: 3.4mm;
  padding: 1.4mm 3.4mm;
  background: var(--paper-accent);
  border-radius: 0;
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.02);
  letter-spacing: 0.12em;
  print-color-adjust: exact;
}

.tw-yadai.layout-formal.resume-paper .paper-style-block .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 4.2mm;
  height: 4.2mm;
  color: #fff;
}

.tw-yadai.layout-formal.resume-paper .paper-style-block .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

.tw-yadai.layout-formal.resume-paper .paper-section__body {
  color: #33434d;
}

/* 条目：日期左栏、单位居中、专业贴右 */
.tw-yadai.layout-formal.resume-paper .paper-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 6mm;
  row-gap: 0.8mm;
}

.tw-yadai.layout-formal.resume-paper .paper-item > * {
  flex: 1 0 100%;
}

.tw-yadai.layout-formal.resume-paper .paper-item > .paper-item-head {
  flex: 0 1 auto;
  justify-content: flex-start;
  gap: 6mm;
}

.tw-yadai.layout-formal.resume-paper .paper-item-head .paper-item-title {
  order: 2;
}

.tw-yadai.layout-formal.resume-paper .paper-item-period {
  order: 1;
  flex: 0 0 auto;
  width: 31mm;
  color: #6f8090;
  font-size: calc(var(--paper-base-size) * 0.86);
  white-space: nowrap;
}

.tw-yadai.layout-formal.resume-paper .paper-item > .paper-item-sub {
  flex: 0 0 auto;
  margin-top: 0;
  margin-left: auto;
  color: #3f505c;
}

.tw-yadai.layout-formal.resume-paper .paper-item-title {
  color: #1f2b33;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-yadai.layout-formal.resume-paper .paper-item-sub span + span::before {
  content: "";
  margin-right: 6mm;
}

.tw-yadai.layout-formal.resume-paper .paper-rich ul,
.tw-yadai.layout-formal.resume-paper .paper-rich ol {
  margin-top: 0.8mm;
  padding-left: 0;
  list-style: none;
}

.tw-yadai.layout-formal.resume-paper .paper-rich li {
  position: relative;
  margin: 0.7mm 0;
  padding-left: 3.6mm;
}

.tw-yadai.layout-formal.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.7em;
  left: 0.4mm;
  width: 1.1mm;
  height: 1.1mm;
  border-radius: 50%;
  background: var(--paper-accent);
  print-color-adjust: exact;
}

.tw-yadai.layout-formal.resume-paper .paper-note__tag {
  color: var(--paper-accent);
  font-weight: 600;
}

/* 主修课程回到正文读法：去掉胶囊边框与内边距 */
.tw-yadai.layout-formal.resume-paper .paper-note__tag {
  display: inline;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
  color: #1d2c35;
  font-weight: 600;
  font-size: inherit;
}

.tw-yadai.layout-formal.resume-paper .paper-note__tag::after {
  content: "：";
}

.tw-yadai.layout-formal.resume-paper .paper-footer {
  border-top: 0.2mm solid #e4e9ee;
  color: #9daab4;
}
